'use strict';
const STORE_KEY='balanceos_local_v1';
const DAY_NAMES=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
const DAY_CODES=['sun','mon','tue','wed','thu','fri','sat'];
const THEORY_COLORS={personal:'#4777a6',family:'#43856b',dawah:'#bf8b42',business:'#8463a4'};
const THEORY_ICONS={personal:'◈',family:'⌂',dawah:'✧',business:'▦'};
const LEVEL_TITLES=['البداية الواعية','بناء العادة','الثبات','التقدم','الإتقان','التوازن','التمكين','الأثر','الاستدامة','الريادة'];
const PROMPTS=['القليل الدائم يصنع أثرًا يتراكم.','اختر خطوة واحدة واضحة ثم ابدأ.','التوازن ليس فعل كل شيء، بل إعطاء كل شيء حقه.','الاستمرار الجيد يتسع للراحة والتعديل.','قِس تقدمك بما تعلمته وما أنجزته، لا بما خططت له فقط.','اليوم فرصة لبداية صغيرة قابلة للتكرار.'];
let state=null, templateOriginal=null, activeView='dashboard', activeTheory='personal', todayFilter='all', pendingCompletionId=null, timePlannerBackupBase64=null;
let focusTick=null, focusPreset=25, focusBreak=false, deferredInstallPrompt=null;
const $=id=>document.getElementById(id);
const clone=x=>JSON.parse(JSON.stringify(x));
const uid=()=>('b'+Date.now().toString(36)+Math.random().toString(36).slice(2,8));
const pad=n=>String(n).padStart(2,'0');
const dateKey=(d=new Date())=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const fromDateKey=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12,0,0)};
const addDays=(key,delta)=>{const d=fromDateKey(key);d.setDate(d.getDate()+delta);return dateKey(d)};
const fmtDate=(key,opts={weekday:'short',day:'numeric',month:'short'})=>fromDateKey(key).toLocaleDateString('ar-EG',opts);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const int=(n,min=0,max=999999)=>Math.max(min,Math.min(max,Number(n)||0));
function normalizeNode(n){n.id=n.id||uid();n.enabled=n.enabled!==false;n.priority=Number(n.priority)||1;n.children=(n.children||[]).map(normalizeNode);if(n.schedule){n.schedule.enabled=n.schedule.enabled!==false;n.schedule.repeat=n.schedule.repeat||'daily';n.schedule.minutes=int(n.schedule.minutes||15,1,600);n.schedule.part=n.schedule.part||'anytime';n.schedule.days=n.schedule.days||DAY_CODES.slice();n.schedule.time=n.schedule.time||'';}return n;}
function normalizeTemplate(t){t.theories.forEach(th=>{th.enabled=th.enabled!==false;th.androidColor=th.androidColor??th.color??-227691;th.color=THEORY_COLORS[th.key]||'#527b72';th.icon=th.icon||THEORY_ICONS[th.key]||'◈';th.sections.forEach(s=>{s.id=s.id||uid();s.enabled=s.enabled!==false;s.tasks=(s.tasks||[]).map(normalizeNode);});});return t;}
function newState(template){return {schemaVersion:1,createdAt:new Date().toISOString(),profile:{name:'صاحب الخطة',dailyGoal:4,restDays:['fri'],vacationMode:false,vacationRanges:[],vacationStartedAt:null,vacationStreakSnapshot:null},theories:clone(template.theories),logs:[],journal:{},goals:[],rewards:[{id:uid(),name:'وقت لهواية تحبها',cost:80,note:'مكافأة شخصية مختارة'},{id:uid(),name:'شراء كتاب أو أداة مفيدة',cost:140,note:'استثمار في التعلم'},{id:uid(),name:'نزهة أو تجربة جديدة',cost:200,note:'وقت للاستمتاع والراحة'}],redemptions:[],xp:0,coins:0,bonuses:{},challengeAwards:{},focus:{},settings:{dailyPromptIndex:Math.floor(Math.random()*PROMPTS.length)}};}
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));$('connectionLabel').textContent='حفظ تلقائي على هذا الجهاز';}catch(e){toast('تعذر الحفظ المحلي؛ صدّر نسخة احتياطية الآن.','error');}}
async function boot(){try{const r=await fetch('./data/balance_templates.json');if(!r.ok)throw new Error('تعذر تحميل القوالب');templateOriginal=normalizeTemplate(await r.json());const raw=localStorage.getItem(STORE_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.schemaVersion===1&&Array.isArray(parsed.theories)){state=parsed;state.profile=state.profile||{name:'صاحب الخطة',dailyGoal:4,restDays:['fri'],vacationMode:false};state.profile.vacationRanges=state.profile.vacationRanges||[];state.logs=state.logs||[];state.journal=state.journal||{};state.goals=state.goals||[];state.rewards=state.rewards||[];state.redemptions=state.redemptions||[];state.bonuses=state.bonuses||{};state.challengeAwards=state.challengeAwards||{};state.focus=state.focus||{};state.settings=state.settings||{dailyPromptIndex:0};state.xp=Number(state.xp)||0;state.coins=Number(state.coins)||0;state.theories.forEach(t=>{t.androidColor=t.androidColor??t.color??-227691;t.color=THEORY_COLORS[t.key]||'#527b72';t.sections?.forEach(s=>{s.id=s.id||uid();s.tasks?.forEach(normalizeNode);});});}else state=newState(templateOriginal);}else state=newState(templateOriginal);save();initApp();if('serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(()=>{});}checkBackend();}catch(e){document.body.innerHTML='<main style="padding:30px;direction:rtl;font-family:Tahoma"><h2>تعذر بدء BalanceOS</h2><p>'+escapeHTML(e.message)+'</p><p>شغّل التطبيق عبر خادم محلي أو استضفه على HTTPS، ولا تفتح index.html مباشرة من مجلد الملفات.</p></main>';}}
function allTasks(){const out=[];state.theories.forEach(th=>{th.sections?.forEach((sec,si)=>{function walk(nodes,path=[],branchEnabled=true){nodes.forEach((n,ni)=>{const chain=branchEnabled&&n.enabled;out.push({node:n,theory:th,section:sec,sectionIndex:si,path:[...path,ni],branchEnabled:chain});walk(n.children||[],[...path,ni],chain);});}walk(sec.tasks||[]);});});return out;}
function activeTasks(){return allTasks().filter(x=>x.theory.enabled&&x.section.enabled&&x.branchEnabled);}
function findTask(id){return allTasks().find(x=>x.node.id===id)||null;}
function findSection(theoryKey,sectionId){const th=state.theories.find(x=>x.key===theoryKey);return th?.sections.find(s=>s.id===sectionId)||null;}
function dateLogs(key=dateKey(),type='task'){return state.logs.filter(x=>x.date===key&&x.type===type);}
function getLog(taskId,key=dateKey()){return state.logs.find(x=>x.type==='task'&&x.taskId===taskId&&x.date===key)||null;}
function taskOccursToday(node,key=dateKey()){
  if(!node.enabled)return false;
  const s=node.schedule; if(s?.enabled){if(s.startDate&&key<s.startDate)return false;if(s.endDate&&key>s.endDate)return false;const dow=DAY_CODES[fromDateKey(key).getDay()];if(s.repeat==='daily')return true;return (s.days||[]).includes(dow);}
  if(node.dueDate&&node.dueDate<=key&&!node.archived&&!node.completed)return true;
  return false;
}
function todayTasks(){return activeTasks().filter(x=>taskOccursToday(x.node)&&(!x.node.schedule?.oneTime||!x.node.completedOnce));}
function doneToday(id){return !!getLog(id,dateKey());}
function taskXP(node){return node.priority>=3?14:node.priority===2?10:8;}
function completedCount(key=dateKey()){return dateLogs(key,'task').length;}
function addRewardXP(xp,coins){state.xp=Math.max(0,(state.xp||0)+xp);state.coins=Math.max(0,(state.coins||0)+coins);}
function refreshBonuses(key=dateKey()){
  const count=completedCount(key), uniqueTheory=new Set(dateLogs(key,'task').map(l=>l.theoryKey)).size;
  const desired={daily:count>=state.profile.dailyGoal?{xp:15,coins:5}:null,balance:uniqueTheory>=3?{xp:15,coins:5}:null};
  state.bonuses[key]=state.bonuses[key]||{};
  ['daily','balance'].forEach(k=>{const old=state.bonuses[key][k];const next=desired[k];if(old&&!next){addRewardXP(-old.xp,-old.coins);state.bonuses[key][k]=null;}else if(!old&&next){addRewardXP(next.xp,next.coins);state.bonuses[key][k]=next;toast(k==='daily'?'تحقق هدفك اليومي! +15 XP':'أنجزت عبر 3 نظريات! +15 XP');}});
}
function toggleTask(taskId,note=''){
  const found=findTask(taskId);if(!found)return;
  const existing=getLog(taskId,dateKey());
  if(existing){state.logs=state.logs.filter(x=>x.id!==existing.id);addRewardXP(-existing.xp-(existing.goalBonusXp||0),-existing.coins-(existing.goalBonusCoins||0));if(existing.goalId){const g=state.goals.find(x=>x.id===existing.goalId);if(g){g.current=Math.max(0,g.current-(existing.goalDelta||1));if(g.current<g.target)g.completed=false;}}if(found.node.dueDate&&!found.node.schedule)found.node.completed=false;toast('تم إلغاء تسجيل الإنجاز.');}
  else{const xp=taskXP(found.node),coins=Math.max(2,Math.round(xp/3));let goalBonusXp=0,goalBonusCoins=0,goalId=found.node.goalId||'';if(goalId){const g=state.goals.find(x=>x.id===goalId);if(g&&!g.completed){g.current=Math.min(g.target,(g.current||0)+1);if(g.current>=g.target){g.completed=true;if(!g.rewarded){goalBonusXp=40;goalBonusCoins=12;g.rewarded=true;}}}else goalId='';}state.logs.push({id:uid(),type:'task',taskId,theoryKey:found.theory.key,theoryName:found.theory.name,sectionName:found.section.name,taskName:found.node.name,date:dateKey(),completedAt:new Date().toISOString(),xp,coins,goalId,goalDelta:goalId?1:0,goalBonusXp,goalBonusCoins,note});addRewardXP(xp+goalBonusXp,coins+goalBonusCoins);if(found.node.dueDate&&!found.node.schedule)found.node.completed=true;toast(`أحسنت! +${xp+goalBonusXp} XP و+${coins+goalBonusCoins} عملات`);}
  refreshBonuses();save();renderAll();
}
function countScheduled(){return todayTasks().length;}
function dailyPercent(){const total=countScheduled(),done=dateLogs(dateKey(),'task').filter(l=>todayTasks().some(t=>t.node.id===l.taskId)).length;return total?Math.round(done/total*100):0;}
function levelInfo(){let thresholds=[0,250,600,1100,1800,2700,3900,5400,7200,9300,11700,14400,17400];let level=1;for(let i=1;i<thresholds.length;i++)if(state.xp>=thresholds[i])level=i+1;else break;const floor=thresholds[level-1]??0,next=thresholds[level]??(floor+3500);return {level,floor,next,progress:Math.min(100,Math.round((state.xp-floor)/(next-floor)*100)),title:LEVEL_TITLES[Math.min(level-1,LEVEL_TITLES.length-1)]||'الاستدامة'};}
function isRestDay(key){const day=DAY_CODES[fromDateKey(key).getDay()];return (state.profile.restDays||[]).includes(day);}
function meetsDailyGoal(key){return dateLogs(key,'task').length>=state.profile.dailyGoal;}
function isVacationDay(key){if((state.profile.vacationRanges||[]).some(r=>key>=r.start&&key<=r.end))return true;return !!(state.profile.vacationMode&&state.profile.vacationStartedAt&&key>=state.profile.vacationStartedAt&&key<=dateKey());}
function calcStreak(){if(state.profile.vacationMode){const frozen=Math.max(0,Number(state.profile.vacationStreakSnapshot)||0);return {current:frozen,label:`إجازة · ${frozen} يوم محفوظة`};}let cursor=dateKey();if(!meetsDailyGoal(cursor))cursor=addDays(cursor,-1);let streak=0;for(let i=0;i<500;i++){if(isRestDay(cursor)||isVacationDay(cursor)){cursor=addDays(cursor,-1);continue;}if(meetsDailyGoal(cursor)){streak++;cursor=addDays(cursor,-1);}else break;}return {current:streak,label:`${streak} يوم`};}
function theoryTaskCounts(key){const list=activeTasks().filter(x=>x.theory.key===key);const done=list.filter(x=>doneToday(x.node.id)).length;return {done,total:list.length};}
function initApp(){const d=new Date();$('todayDate').textContent=d.toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('datePill').textContent=fmtDate(dateKey(),{weekday:'long',day:'numeric',month:'long'});$('journalDate').value=dateKey();$('journalDate').max=dateKey();$('taskDaysInput').innerHTML=DAY_NAMES.map((n,i)=>`<label><input type="checkbox" value="${DAY_CODES[i]}" ${i<5?'checked':''}> ${n.slice(0,2)}</label>`).join('');
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;$('installApp').classList.remove('hidden');});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;$('installApp').classList.add('hidden');toast('تم تثبيت BalanceOS على جهازك.');});$('installApp').addEventListener('click',async()=>{if(!deferredInstallPrompt){toast('يمكنك تثبيت التطبيق من قائمة المتصفح: تثبيت التطبيق أو إضافة إلى الشاشة الرئيسية.');return;}deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('installApp').classList.add('hidden');});
  document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
  $('mobileMenu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
  $('quickAddTop').addEventListener('click',()=>openTaskDialog());$('profileChip').addEventListener('click',()=>navigate('settings'));
  document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.goto)));
  $('addTodayTask').addEventListener('click',()=>openTaskDialog());$('addHabitBtn').addEventListener('click',()=>openTaskDialog(null,true));$('addGoalBtn').addEventListener('click',openGoalDialog);$('addRewardBtn').addEventListener('click',()=>$('rewardDialog').showModal());$('addTheoryBtn').addEventListener('click',addTheory);
  $('taskScheduleInput').addEventListener('change',()=> $('taskScheduleOptions').classList.toggle('hidden',!$('taskScheduleInput').checked));
  $('taskForm').addEventListener('submit',saveTaskFromDialog);$('goalForm').addEventListener('submit',saveGoalFromDialog);$('rewardForm').addEventListener('submit',saveRewardFromDialog);
  $('todayFilters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;todayFilter=b.dataset.filter;document.querySelectorAll('#todayFilters .filter-pill').forEach(x=>x.classList.toggle('active',x===b));renderToday();});
  $('todayTheoryFilter').addEventListener('change',renderToday);$('theorySwitcher').addEventListener('click',e=>{const b=e.target.closest('[data-theory]');if(!b)return;activeTheory=b.dataset.theory;renderPlans();});$('theoryContent').addEventListener('click',planAction);
  $('todayTaskGroups').addEventListener('click',e=>{const b=e.target.closest('[data-complete]');if(b)toggleTask(b.dataset.complete);});$('dashboardTasks').addEventListener('click',e=>{const b=e.target.closest('[data-complete]');if(b)toggleTask(b.dataset.complete);});$('habitList').addEventListener('click',e=>{const b=e.target.closest('[data-habit]');if(b)toggleTask(b.dataset.habit);});
  $('goalList').addEventListener('click',goalAction);$('rewardShop').addEventListener('click',rewardAction);$('saveJournal').addEventListener('click',saveJournal);$('journalDate').addEventListener('change',loadJournal);
  $('analyticsRange').addEventListener('change',renderAnalytics);$('focusStart').addEventListener('click',focusStartPause);$('focusReset').addEventListener('click',focusReset);$('focusFinish').addEventListener('click',focusFinish);document.querySelectorAll('.focus-preset').forEach(b=>b.addEventListener('click',()=>setFocusPreset(+b.dataset.min,b.dataset.break==='1')));
  $('saveSettings').addEventListener('click',saveSettings);$('exportBackup').addEventListener('click',exportBackup);$('importBackup').addEventListener('change',importBackup);$('exportCSV').addEventListener('click',exportCSV);$('exportTPConfig').addEventListener('click',exportTimePlannerConfig);$('exportTimePlanner').addEventListener('click',exportTimePlannerDB);$('importTPDb').addEventListener('change',importTimePlannerDb);$('resetApp').addEventListener('click',resetApp);
  $('restDaysEditor').innerHTML=DAY_NAMES.map((n,i)=>`<label class="rest-day"><input type="checkbox" value="${DAY_CODES[i]}"> ${n.slice(0,2)}</label>`).join('');populateSelectors();loadSettings();renderAll();setFocusPreset(25,false);updateConnection();}
function navigate(view){activeView=view;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));document.querySelectorAll('.nav-link,.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={dashboard:'نظرة عامة',today:'يومي',plans:'نظريات التوازن',habits:'العادات والروتين',goals:'الأهداف والمشروعات',journal:'السجل اليومي',focus:'التركيز',analytics:'التحليلات والتقدم',rewards:'الإنجازات والمكافآت',settings:'الإعدادات والنسخ'};$('viewTitle').textContent=titles[view]||'BalanceOS';$('sidebar').classList.remove('open');if(view==='journal')loadJournal();if(view==='settings')loadSettings();renderAll();window.scrollTo({top:0,behavior:'smooth'});}
function theoryColor(key){const th=state.theories.find(x=>x.key===key);return th?.color||THEORY_COLORS[key]||'#69857b';}
function theoryIcon(key){const th=state.theories.find(x=>x.key===key);return th?.icon||THEORY_ICONS[key]||'◈';}
function renderAll(){if(!state)return;renderProfile();renderDashboard();renderToday();renderPlans();renderHabits();renderGoals();renderJournalStats();renderFocus();renderAnalytics();renderRewards();if(activeView==='settings')loadSettings();}
function renderProfile(){$('profileNameTop').textContent=state.profile.name||'صاحب الخطة';$('profileMini').innerHTML=`<span class="avatar-dot">✦</span><div><b>${escapeHTML(state.profile.name||'صاحب الخطة')}</b><small>المستوى ${levelInfo().level} · ${state.xp} نقطة خبرة</small></div>`;$('welcomeTitle').textContent=`مرحبًا ${state.profile.name||'بك'}، ابدأ بخطوة واضحة واستمر بإيقاع متوازن.`;}
function renderDashboard(){const today=dateKey(),tasks=todayTasks(),done=tasks.filter(x=>doneToday(x.node.id)).length,total=tasks.length,percent=total?Math.round(done/total*100):0,lv=levelInfo(),streak=calcStreak();$('levelBadge').textContent='المستوى '+lv.level;$('levelNumber').textContent=String(lv.level).padStart(2,'0');$('levelTitle').textContent=lv.title;$('xpText').textContent=`${state.xp} / ${lv.next} XP`;$('xpNext').textContent=`${Math.max(0,lv.next-state.xp)} XP للمستوى التالي`;$('xpBar').style.width=lv.progress+'%';$('doneCount').textContent=done;$('totalCount').textContent=total;$('todayPercent').textContent=percent+'%';$('todayBar').style.width=percent+'%';$('dailyGoalText').textContent=`هدفك اليومي: ${state.profile.dailyGoal} مهام`;$('streakText').textContent=state.profile.vacationMode?`🌿 إجازة · ${streak.current} يوم محفوظة`:`🔥 ${streak.current} يوم`;
  const last7=Array.from({length:7},(_,i)=>addDays(today,-i));const weekDone=last7.reduce((n,k)=>n+dateLogs(k,'task').length,0);const focusMin=last7.reduce((n,k)=>n+dateLogs(k,'focus').reduce((s,x)=>s+(x.minutes||0),0),0);const activeGoals=state.goals.filter(g=>!g.completed);$('dashboardStats').innerHTML=[['✦','إجمالي الخبرة',state.xp+' XP','تتراكم مع الإنجاز'],['♜','العملات',state.coins,'للمكافآت الشخصية'],['✓','إنجازات آخر 7 أيام',weekDone,'مهام مكتملة'],['◷','وقت التركيز',focusMin+' د','آخر 7 أيام']].map(x=>`<div class="stat-card"><span class="stat-icon">${x[0]}</span><div class="stat-label">${x[1]}</div><strong>${x[2]}</strong><small>${x[3]}</small></div>`).join('');
  const sorted=tasks.filter(x=>!doneToday(x.node.id)).sort((a,b)=>(b.node.priority||1)-(a.node.priority||1)).slice(0,5);$('dashboardTasks').innerHTML=sorted.length?sorted.map(x=>taskRow(x,false)).join(''):'<div class="empty-mini">أكملت مهامك المجدولة أو لم تحدد مهامًا لهذا اليوم. أحسنت في ضبط الإيقاع.</div>';
  $('balanceBars').innerHTML=state.theories.filter(t=>t.enabled).map(th=>{const list=dateLogs(today,'task').filter(l=>l.theoryKey===th.key);const p=total?Math.round(list.length/Math.max(1,total)*100):0;return `<div class="balance-item"><div class="balance-item-head"><span><i class="theory-dot" style="background:${th.color}"></i>${escapeHTML(th.name.replace('نظرية التوازن ','').replace('نظرية ','').replace('نظرية توازن ',''))}</span><span>${list.length} إنجاز · ${p}%</span></div><div class="balance-progress"><span style="width:${p}%;background:${th.color}"></span></div></div>`}).join('')||'<div class="empty-mini">فعّل نظرية واحدة على الأقل.</div>';
  $('dailyPrompt').textContent=PROMPTS[(new Date().getDate()+state.settings.dailyPromptIndex)%PROMPTS.length];$('goalPreview').innerHTML=activeGoals.slice(0,3).map(g=>`<div class="goal-preview"><h4>${escapeHTML(g.name)}</h4><div class="muted">${escapeHTML(g.theoryName||'هدف شخصي')}</div><div class="progress-track"><span style="width:${goalPercent(g)}%"></span></div><div class="muted">${goalPercent(g)}% من الهدف</div></div>`).join('')||'<div class="empty-mini">أضف هدفًا طويل المدى لربطه بمهامك.</div>';}
function taskRow(x,showTheory=true){const n=x.node,done=doneToday(n.id),p=n.priority>=3?'high':n.priority===1?'low':'';return `<div class="task-row ${done?'done':''}"><button class="task-check" data-complete="${n.id}" title="تسجيل الإنجاز">✓</button><div class="task-row-main"><div class="task-row-title">${escapeHTML(n.name)}</div><div class="task-row-meta">${showTheory?`<span><i class="theory-dot" style="background:${x.theory.color}"></i>${escapeHTML(x.theory.name.replace('نظرية التوازن ','').replace('نظرية ','').replace('نظرية توازن ',''))}</span>`:''}<span>${escapeHTML(x.section.name)}</span>${n.schedule?`<span>· ${n.schedule.minutes||15} د</span>`:''}<span class="priority ${p}">${n.priority>=3?'عالية':n.priority===1?'منخفضة':'متوسطة'}</span></div></div><button class="tiny-action" data-edit-task="${n.id}" title="تعديل" onclick="window.editTask('${n.id}')">✎</button></div>`;}
function renderToday(){const tasks=todayTasks(),done=tasks.filter(x=>doneToday(x.node.id)).length,open=tasks.length-done,filter=$('todayTheoryFilter').value||'all';$('todaySummary').innerHTML=[['المهام المجدولة',tasks.length],['تم إنجازها',done],['المتبقي',open],['نسبة الإنجاز',tasks.length?Math.round(done/tasks.length*100)+'%':'—']].map(x=>`<div class="summary-tile"><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('');const filtered=tasks.filter(x=>(filter==='all'||x.theory.key===filter)&&(todayFilter==='all'||(todayFilter==='done'?doneToday(x.node.id):!doneToday(x.node.id))));const grouped={};filtered.forEach(x=>(grouped[x.theory.key]??=[]).push(x));$('todayTaskGroups').innerHTML=Object.keys(grouped).map(k=>{const th=state.theories.find(t=>t.key===k);const arr=grouped[k];return `<div class="task-group"><div class="task-group-head"><i class="theory-dot" style="background:${th.color}"></i>${escapeHTML(th.name)}<span class="task-group-count">${arr.filter(x=>doneToday(x.node.id)).length}/${arr.length}</span></div><div class="task-list">${arr.map(x=>taskRow(x,false)).join('')}</div></div>`}).join('');$('todayEmpty').classList.toggle('hidden',tasks.length>0);$('todayTaskGroups').classList.toggle('hidden',tasks.length===0);}
function populateSelectors(){const opts=state.theories.filter(t=>t.enabled).map(t=>t.sections.map((s,i)=>`<option value="${t.key}|${s.id}">${escapeHTML(t.name)} — ${escapeHTML(s.name)}</option>`).join('')).join('');$('taskSectionSelect').innerHTML=opts||'<option value="">لا توجد أقسام فعالة</option>';$('goalTheoryInput').innerHTML=state.theories.map(t=>`<option value="${t.key}">${escapeHTML(t.name)}</option>`).join('');$('taskGoalInput').innerHTML='<option value="">بدون ربط بهدف</option>'+state.goals.filter(g=>!g.completed).map(g=>`<option value="${g.id}">${escapeHTML(g.name)}</option>`).join('');$('todayTheoryFilter').innerHTML='<option value="all">كل النظريات</option>'+state.theories.map(t=>`<option value="${t.key}">${escapeHTML(t.name)}</option>`).join('');}
function renderPlans(){populateSelectors();$('theorySwitcher').innerHTML=state.theories.map(t=>`<button class="theory-tab ${activeTheory===t.key?'active':''}" data-theory="${t.key}"><i class="theory-dot" style="background:${t.color}"></i>${escapeHTML(t.name)}</button>`).join('');let th=state.theories.find(t=>t.key===activeTheory)||state.theories[0];if(!th){$('theoryContent').innerHTML='<div class="empty-state">لا توجد نظريات.</div>';return;}const all=allTasks().filter(x=>x.theory.key===th.key&&x.theory.enabled&&x.section.enabled);const done=all.filter(x=>state.logs.some(l=>l.type==='task'&&l.taskId===x.node.id)).length;$('theoryContent').innerHTML=`<article class="theory-card"><div class="theory-card-head"><div class="theory-icon" style="color:${th.color}">${th.icon}</div><div class="theory-title"><h3>${escapeHTML(th.name)}</h3><p>${escapeHTML(th.note||'خصص هذه النظرية بما يناسب أهدافك ومرحلتك.')}</p></div><div class="theory-stat">${done} إنجازات مسجلة · ${all.length} عنصر</div><label class="check-row"><input type="checkbox" ${th.enabled?'checked':''} onchange="window.toggleTheory('${th.key}',this.checked)"> مفعّلة</label></div><div class="theory-card-body">${th.sections.map(sec=>`<div class="plan-section"><div class="plan-section-head"><strong>${escapeHTML(sec.name)}</strong><small>${countNodes(sec.tasks)} عناصر</small><label class="check-row"><input type="checkbox" ${sec.enabled?'checked':''} onchange="window.toggleSection('${th.key}','${sec.id}',this.checked)"> تضمين</label><button class="tiny-action" onclick="window.renameSection('${th.key}','${sec.id}')">✎</button><button class="tiny-action" onclick="window.addTaskToSection('${th.key}','${sec.id}')">＋</button></div><div class="plan-section-body">${sec.tasks.map(n=>renderTreeNode(n,th.key,sec.id,0)).join('')}<button class="add-inline" onclick="window.addTaskToSection('${th.key}','${sec.id}')">＋ إضافة عنصر أساسي</button></div></div>`).join('')}<button class="btn btn-secondary" onclick="window.addSection('${th.key}')">＋ إضافة قسم جديد</button> <button class="btn btn-ghost" onclick="window.editTheory('${th.key}')">تعديل وصف النظرية</button></div></article>`;}
function countNodes(nodes){return nodes.reduce((n,x)=>n+1+countNodes(x.children||[]),0);}
function renderTreeNode(n,theoryKey,sectionId,depth){const isDone=doneToday(n.id);return `<div class="tree-task" style="margin-right:${Math.min(depth*12,48)}px"><div class="tree-task-main"><button class="task-check ${isDone?'done':''}" onclick="window.completeTask('${n.id}')">✓</button><div class="task-text"><b>${escapeHTML(n.name)}</b><small>${escapeHTML(n.note||'')}${n.schedule?.enabled?' · مجدولة':''}</small></div><div class="tree-task-actions"><button title="جدولة" onclick="window.toggleSchedule('${n.id}')">◷</button><button title="إضافة فرعية" onclick="window.addChild('${n.id}')">＋</button><button title="تعديل" onclick="window.editTask('${n.id}')">✎</button><button title="حذف" onclick="window.deleteTask('${n.id}')">×</button></div></div>${(n.children||[]).length?`<div class="tree-children">${n.children.map(c=>renderTreeNode(c,theoryKey,sectionId,depth+1)).join('')}</div>`:''}</div>`;}
function planAction(e){const b=e.target.closest('[data-action]');if(!b)return;}
function addTheory(){const name=prompt('اسم النظرية أو المجال الجديد:','نظرية توازن جديدة');if(!name)return;const key='custom_'+uid();state.theories.push({key,name,note:'نظرية مخصصة — أضف الأقسام والعناصر التي تناسبك.',enabled:true,color:'#5d8276',icon:'◇',sections:[{id:uid(),name:'القسم الأول',note:'',enabled:true,tasks:[]},{id:uid(),name:'القسم الثاني',note:'',enabled:true,tasks:[]},{id:uid(),name:'القسم الثالث',note:'',enabled:true,tasks:[]}]});activeTheory=key;save();renderAll();toast('تم إنشاء نظرية مخصصة.');}
window.toggleTheory=(key,v)=>{const t=state.theories.find(x=>x.key===key);if(t)t.enabled=v;save();renderAll();};
window.toggleSection=(key,id,v)=>{const s=findSection(key,id);if(s)s.enabled=v;save();renderAll();};
window.renameSection=(key,id)=>{const s=findSection(key,id);if(!s)return;const n=prompt('اسم القسم:',s.name);if(n?.trim()){s.name=n.trim();save();renderAll();}};
window.addSection=key=>{const th=state.theories.find(x=>x.key===key);const n=prompt('اسم القسم الجديد:','قسم جديد');if(n?.trim()){th.sections.push({id:uid(),name:n.trim(),note:'',enabled:true,tasks:[]});save();renderAll();}};
window.addTaskToSection=(key,id)=>{openTaskDialog(null,false,key,id);};
window.editTheory=key=>{const th=state.theories.find(x=>x.key===key);const n=prompt('اسم النظرية:',th.name);if(n?.trim())th.name=n.trim();const note=prompt('وصف النظرية:',th.note||'');if(note!==null)th.note=note;save();renderAll();};
window.addChild=id=>{const f=findTask(id);if(!f)return;const name=prompt('اسم المهمة الفرعية:','خطوة جديدة');if(!name?.trim())return;f.node.children.push({id:uid(),name:name.trim(),note:'',enabled:true,priority:1,children:[]});save();renderAll();toast('أضيفت المهمة الفرعية.');};
window.deleteTask=id=>{const f=findTask(id);if(!f)return;if(!confirm('حذف المهمة وكل تفريعاتها؟'))return;f.node.enabled=false;f.node.archived=true;state.logs=state.logs.filter(l=>l.taskId!==id);save();renderAll();};
window.toggleSchedule=id=>{const f=findTask(id);if(!f)return;if(!f.node.schedule)f.node.schedule={enabled:true,repeat:'daily',minutes:15,part:'anytime',days:DAY_CODES.slice(),time:''};else f.node.schedule.enabled=!f.node.schedule.enabled;save();renderAll();toast(f.node.schedule.enabled?'تمت إضافة المهمة إلى الروتين.':'تم إيقاف الجدولة.');};
window.completeTask=id=>toggleTask(id);
window.editTask=id=>openTaskDialog(id);
function openTaskDialog(taskId=null,habitMode=false,forceTheory=null,forceSection=null){populateSelectors();const f=taskId?findTask(taskId):null;$('taskDialogTitle').textContent=f?'تعديل المهمة':habitMode?'إضافة عادة جديدة':'مهمة جديدة';$('editTaskId').value=taskId||'';$('taskNameInput').value=f?.node.name||'';$('taskNoteInput').value=f?.node.note||'';$('taskPriorityInput').value=f?.node.priority||2;$('taskDueInput').value=f?.node.dueDate||(activeView==='today'?dateKey():'');$('taskGoalInput').value=f?.node.goalId||'';$('taskScheduleInput').checked=habitMode||!!f?.node.schedule?.enabled;$('taskScheduleOptions').classList.toggle('hidden',!$('taskScheduleInput').checked);$('taskSectionSelect').disabled=!!f;if(f)$('taskSectionSelect').value=`${f.theory.key}|${f.section.id}`;else if(forceTheory&&forceSection)$('taskSectionSelect').value=`${forceTheory}|${forceSection}`;
  const s=f?.node.schedule||{};$('taskRepeatInput').value=s.repeat||'daily';$('taskMinutesInput').value=s.minutes||15;$('taskTimeInput').value=s.time||'08:00';$('taskPartInput').value=s.part||'morning';document.querySelectorAll('#taskDaysInput input').forEach(i=>i.checked=(s.days||DAY_CODES.slice(0,5)).includes(i.value));$('taskDialog').showModal();}
function saveTaskFromDialog(e){e.preventDefault();const name=$('taskNameInput').value.trim();if(!name){toast('اكتب اسم المهمة أولًا.','error');return;}const [theoryKey,sectionId]=$('taskSectionSelect').value.split('|');const section=findSection(theoryKey,sectionId);if(!section){toast('اختر قسمًا صالحًا.','error');return;}const id=$('editTaskId').value;let node=id?findTask(id)?.node:null;const scheduling=$('taskScheduleInput').checked;let sch=null;if(scheduling){const days=[...document.querySelectorAll('#taskDaysInput input:checked')].map(x=>x.value);sch={enabled:true,repeat:$('taskRepeatInput').value,minutes:int($('taskMinutesInput').value,1,600),time:$('taskTimeInput').value,part:$('taskPartInput').value,days:days.length?days:DAY_CODES.slice(0,5)};}
  if(node){node.name=name;node.note=$('taskNoteInput').value;node.priority=+$('taskPriorityInput').value;node.dueDate=$('taskDueInput').value||'';node.goalId=$('taskGoalInput').value||'';node.schedule=scheduling?sch:null;}else{section.tasks.push({id:uid(),name,note:$('taskNoteInput').value,priority:+$('taskPriorityInput').value,enabled:true,dueDate:$('taskDueInput').value||'',goalId:$('taskGoalInput').value||'',schedule:sch,children:[]});}
  save();$('taskDialog').close();renderAll();toast(id?'تم تحديث المهمة.':'تمت إضافة المهمة.');}
function renderHabits(){const habits=activeTasks().filter(x=>x.node.schedule?.enabled&&x.node.schedule.repeat);const today=habits.filter(x=>taskOccursToday(x.node));const done=today.filter(x=>doneToday(x.node.id)).length;const weekCount=Array.from({length:7},(_,i)=>addDays(dateKey(),-i)).reduce((sum,k)=>sum+dateLogs(k,'task').length,0);$('habitDateLabel').textContent=fmtDate(dateKey(),{weekday:'long',day:'numeric',month:'short'});$('habitSummary').innerHTML=[['العادات النشطة',habits.length],['عادات اليوم',`${done}/${today.length}`],['إنجازات آخر أسبوع',weekCount]].map(x=>`<div class="habit-metric"><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('');$('habitList').innerHTML=today.map(x=>`<div class="habit-card ${doneToday(x.node.id)?'done':''}"><button class="habit-check" data-habit="${x.node.id}">✓</button><div class="habit-info"><b>${escapeHTML(x.node.name)}</b><small>${escapeHTML(x.theory.name)} · ${x.node.schedule.minutes||15} دقيقة · ${x.node.schedule.time||'وقت مرن'}</small></div><span class="tiny-pill">${x.node.schedule.repeat==='daily'?'يومي':'أسبوعي'}</span></div>`).join('')||'<div class="empty-note">لا توجد عادات مجدولة. افتح خططك وجدول العناصر التي تريد تكرارها.</div>';}
function openGoalDialog(){$('goalForm').reset();populateSelectors();$('goalTargetInput').value=10;$('goalUnitInput').value='خطوة';$('goalDialog').showModal();}
function saveGoalFromDialog(e){e.preventDefault();const name=$('goalNameInput').value.trim();if(!name)return;const key=$('goalTheoryInput').value,th=state.theories.find(t=>t.key===key);state.goals.push({id:uid(),name,theoryKey:key,theoryName:th?.name||'هدف عام',description:$('goalDescInput').value,target:int($('goalTargetInput').value,1,999999),current:0,unit:$('goalUnitInput').value||'خطوة',dueDate:$('goalDueInput').value||'',createdAt:new Date().toISOString(),completed:false,rewarded:false});save();$('goalDialog').close();renderAll();toast('تم إنشاء الهدف.');}
function goalPercent(g){return Math.min(100,Math.round((g.current||0)/Math.max(1,g.target)*100));}
function renderGoals(){const active=state.goals.filter(g=>!g.completed),complete=state.goals.filter(g=>g.completed);$('goalKpis').innerHTML=[['أهداف نشطة',active.length],['أهداف مكتملة',complete.length],['متوسط التقدم',active.length?Math.round(active.reduce((s,g)=>s+goalPercent(g),0)/active.length)+'%':'—']].map(x=>`<div class="habit-metric"><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('');$('goalList').innerHTML=state.goals.map(g=>`<div class="goal-card"><div class="goal-card-top"><h3>${escapeHTML(g.name)}</h3><span class="tiny-pill">${g.completed?'مكتمل':goalPercent(g)+'%'}</span></div><p>${escapeHTML(g.description||g.theoryName||'هدف شخصي')}</p><div class="muted small">${escapeHTML(g.theoryName||'عام')} ${g.dueDate?'· الموعد '+fmtDate(g.dueDate,{day:'numeric',month:'short',year:'numeric'}):''}</div><div class="progress-track"><span style="width:${goalPercent(g)}%"></span></div><div class="goal-card-foot"><span>${g.current} / ${g.target} ${escapeHTML(g.unit)}</span><span>${goalPercent(g)}%</span></div><div class="goal-controls"><button class="btn btn-secondary" data-goal-inc="${g.id}" ${g.completed?'disabled':''}>+ خطوة</button><button class="btn btn-ghost" data-goal-edit="${g.id}">تعديل</button><button class="btn btn-ghost" data-goal-done="${g.id}">${g.completed?'إعادة فتح':'إنهاء'}</button></div></div>`).join('')||'<div class="empty-state"><h3>لا توجد أهداف بعد</h3><p>أنشئ هدفًا واضحًا ثم حوّله إلى خطوات صغيرة قابلة للتنفيذ.</p></div>';}
function goalAction(e){const b=e.target.closest('button');if(!b)return;const g=state.goals.find(x=>x.id===b.dataset.goalInc||x.id===b.dataset.goalEdit||x.id===b.dataset.goalDone);if(!g)return;if(b.dataset.goalInc){g.current=Math.min(g.target,g.current+1);if(g.current>=g.target&&!g.completed){g.completed=true;addRewardXP(40,12);toast('اكتمل الهدف! +40 XP');}else toast('تم تحديث تقدم الهدف.');}else if(b.dataset.goalEdit){const n=prompt('تعديل اسم الهدف:',g.name);if(n?.trim())g.name=n.trim();const val=prompt(`التقدم الحالي (${g.unit}):`,g.current);if(val!==null)g.current=int(val,0,g.target);}else if(b.dataset.goalDone){g.completed=!g.completed;if(g.completed){if(g.current<g.target)g.current=g.target;if(!g.rewarded){addRewardXP(40,12);g.rewarded=true;}}}save();renderAll();}
function saveJournal(){const key=$('journalDate').value||dateKey();state.journal[key]={mood:$('journalMood').value,energy:+$('journalEnergy').value,wins:$('journalWins').value,learning:$('journalLearning').value,challenge:$('journalChallenge').value,tomorrow:$('journalTomorrow').value,updatedAt:new Date().toISOString()};save();$('journalSaved').textContent='تم حفظ السجل';renderJournalStats();toast('حُفظ السجل اليومي.');}
function loadJournal(){const key=$('journalDate').value||dateKey(),j=state.journal[key]||{};$('journalMood').value=j.mood||'';$('journalEnergy').value=String(j.energy||3);$('journalWins').value=j.wins||'';$('journalLearning').value=j.learning||'';$('journalChallenge').value=j.challenge||'';$('journalTomorrow').value=j.tomorrow||'';$('journalSaved').textContent=j.updatedAt?'آخر حفظ '+new Date(j.updatedAt).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'}):'';renderJournalStats();}
function renderJournalStats(){if(!$('journalDayStats'))return;const key=$('journalDate').value||dateKey();const j=state.journal[key]||{};$('journalDayStats').innerHTML=[['مهام مكتملة',dateLogs(key,'task').length],['جلسات تركيز',dateLogs(key,'focus').length],['وقت التركيز',dateLogs(key,'focus').reduce((s,x)=>s+(x.minutes||0),0)+' دقيقة'],['الحالة',j.mood||'لم تسجل']].map(x=>`<div class="journal-summary-tile"><b>${x[0]}</b><span>${escapeHTML(String(x[1]))}</span></div>`).join('');$('recentJournal').innerHTML=Object.keys(state.journal).sort().reverse().slice(0,5).map(k=>`<div class="recent-entry"><b>${fmtDate(k,{day:'numeric',month:'short'})}</b><p>${escapeHTML(state.journal[k].wins||state.journal[k].learning||'تم تسجيل اليوم')}</p></div>`).join('')||'<div class="empty-note">لا توجد سجلات سابقة.</div>';}
function setFocusPreset(min,isBreak=false){focusPreset=min;focusBreak=isBreak;document.querySelectorAll('.focus-preset').forEach(b=>b.classList.toggle('active',+b.dataset.min===min&&(b.dataset.break==='1')===isBreak));if(!state.focus.running){state.focus.remaining=min*60;state.focus.total=min*60;updateFocusClock();}}
function focusStartPause(){if(state.focus.running){state.focus.running=false;state.focus.remaining=Math.max(0,Math.ceil((state.focus.endAt-Date.now())/1000));save();updateFocusClock();$('focusStart').textContent='استئناف';clearInterval(focusTick);return;}if(!state.focus.remaining)state.focus.remaining=focusPreset*60;state.focus.total=state.focus.total||focusPreset*60;state.focus.startAt=state.focus.startAt||Date.now();state.focus.endAt=Date.now()+state.focus.remaining*1000;state.focus.running=true;$('focusStart').textContent='إيقاف مؤقت';clearInterval(focusTick);focusTick=setInterval(()=>{state.focus.remaining=Math.max(0,Math.ceil((state.focus.endAt-Date.now())/1000));updateFocusClock();if(state.focus.remaining<=0){focusFinish(true);}},500);save();updateFocusClock();}
function focusReset(){clearInterval(focusTick);state.focus={running:false,remaining:focusPreset*60,total:focusPreset*60};save();updateFocusClock();$('focusStart').textContent='ابدأ التركيز';}
function focusFinish(auto=false){clearInterval(focusTick);const f=state.focus||{};const elapsed=Math.max(0,Math.round(((f.total||0)-(f.remaining||0))/60));if(elapsed>=10){const xp=Math.min(25,Math.round(elapsed/5)),coins=Math.max(2,Math.round(xp/4));state.logs.push({id:uid(),type:'focus',date:dateKey(),completedAt:new Date().toISOString(),minutes:elapsed,xp,coins,taskId:$('focusTask').value||'',taskName:findTask($('focusTask').value)?.node.name||'جلسة تركيز'});addRewardXP(xp,coins);toast(`سُجلت جلسة ${elapsed} دقيقة · +${xp} XP`);}else if(elapsed>0&&!auto)toast('سُجلت الجلسة دون نقاط لأنها أقل من 10 دقائق.');state.focus={running:false,remaining:focusPreset*60,total:focusPreset*60};save();renderFocus();renderDashboard();updateFocusClock();$('focusStart').textContent='ابدأ التركيز';}
function updateFocusClock(){const f=state.focus||{},sec=f.running?Math.max(0,Math.ceil((f.endAt-Date.now())/1000)):(f.remaining??focusPreset*60);$('focusClock').textContent=`${pad(Math.floor(sec/60))}:${pad(sec%60)}`;$('focusStatus').textContent=f.running?'جارٍ التركيز':focusBreak?'استراحة':'جاهز للبدء';$('focusRing').style.background=`conic-gradient(rgba(137,202,174,.45) ${(1-sec/Math.max(1,f.total||focusPreset*60))*360}deg, transparent 0)`;}
function renderFocus(){const tasks=activeTasks();$('focusTask').innerHTML='<option value="">جلسة عامة</option>'+tasks.map(x=>`<option value="${x.node.id}">${escapeHTML(x.node.name)}</option>`).join('');const today=dateLogs(dateKey(),'focus');$('focusTodayTotal').innerHTML=`${today.reduce((s,x)=>s+x.minutes,0)} <span>دقيقة</span>`;$('focusSessionsToday').innerHTML=today.map(x=>`<div class="session-item">${x.minutes} دقيقة · ${escapeHTML(x.taskName||'جلسة تركيز')}</div>`).join('')||'<div class="empty-note">لم تسجل جلسات بعد.</div>';if(state.focus.running){clearInterval(focusTick);focusTick=setInterval(()=>{state.focus.remaining=Math.max(0,Math.ceil((state.focus.endAt-Date.now())/1000));updateFocusClock();if(state.focus.remaining<=0)focusFinish(true);},500);$('focusStart').textContent='إيقاف مؤقت';}else{$('focusStart').textContent='ابدأ التركيز';updateFocusClock();}}
function renderAnalytics(){const days=int($('analyticsRange').value||7,7,90),keys=Array.from({length:days},(_,i)=>addDays(dateKey(),-(days-1-i)));const done=keys.reduce((s,k)=>s+dateLogs(k,'task').length,0),focus=keys.reduce((s,k)=>s+dateLogs(k,'focus').reduce((a,x)=>a+x.minutes,0),0),journals=keys.filter(k=>state.journal[k]).length,avg=Math.round(done/days*10)/10;$('analyticsKpis').innerHTML=[['المهام المكتملة',done],['متوسط الإنجاز اليومي',avg],['وقت التركيز',focus+' د'],['أيام سجلت فيها',journals]].map(x=>`<div class="stat-card"><div class="stat-label">${x[0]}</div><strong>${x[1]}</strong></div>`).join('');const vals=keys.map(k=>dateLogs(k,'task').length),max=Math.max(1,...vals);$('completionChart').innerHTML=keys.map((k,i)=>`<div class="bar-col"><span class="bar-val">${vals[i]}</span><div class="bar-fill" style="height:${Math.max(3,vals[i]/max*145)}px"></div><span class="bar-lab">${fmtDate(k,{day:'numeric',month:days<=7?'short':undefined})}</span></div>`).join('');const totals=state.theories.map(t=>({t,n:keys.reduce((s,k)=>s+dateLogs(k,'task').filter(l=>l.theoryKey===t.key).length,0)}));const sum=totals.reduce((s,x)=>s+x.n,0)||1;$('theoryChart').innerHTML=totals.map(x=>`<div class="theory-chart-row"><span>${escapeHTML(x.t.name.replace('نظرية التوازن ','').replace('نظرية ','').replace('نظرية توازن ',''))}</span><div class="theory-chart-track"><span style="width:${x.n/sum*100}%;background:${x.t.color}"></span></div><b>${x.n}</b></div>`).join('');const thisWeek=Array.from({length:7},(_,i)=>addDays(dateKey(),-6+i)),prev=Array.from({length:7},(_,i)=>addDays(dateKey(),-13+i)),w=thisWeek.reduce((s,k)=>s+dateLogs(k,'task').length,0),p=prev.reduce((s,k)=>s+dateLogs(k,'task').length,0);const strongest=totals.slice().sort((a,b)=>b.n-a.n)[0];const journals7=Object.keys(state.journal).filter(k=>k>=addDays(dateKey(),-6)&&k<=dateKey()).length;$('weeklyReview').innerHTML=`<div class="review-grid"><div class="review-box"><b>مقارنة الأسبوع السابق</b><p>${w} إنجازًا هذا الأسبوع مقابل ${p} الأسبوع السابق. ${w>p?'اتجاه إيجابي.':w<p?'راجع ضغط الخطة والعوائق.':'مستوى قريب من الأسبوع السابق.'}</p></div><div class="review-box"><b>أكثر نظرية نشاطًا</b><p>${strongest?.t.name||'لا توجد بيانات'} — ${strongest?.n||0} إنجازات خلال الفترة المحددة.</p></div><div class="review-box"><b>السجل والتأمل</b><p>${journals7} أيام موثقة خلال آخر أسبوع. حاول تسجيل ما تعلمته والعائق الأهم.</p></div></div>`;}
function badges(){const tasks=state.logs.filter(l=>l.type==='task').length,focus=state.logs.filter(l=>l.type==='focus').reduce((s,x)=>s+x.minutes,0),journals=Object.keys(state.journal).length,streak=calcStreak().current,unique=new Set(state.logs.filter(l=>l.type==='task').map(l=>l.theoryKey)).size;return [{id:'first',icon:'🌱',name:'أول خطوة',desc:'سجل أول إنجاز',earned:tasks>=1},{id:'ten',icon:'✦',name:'عشر خطوات',desc:'أكمل 10 مهام',earned:tasks>=10},{id:'steady',icon:'🔥',name:'استمرارية',desc:'حقق الهدف 7 أيام متتالية',earned:streak>=7},{id:'focus',icon:'◷',name:'وقت عميق',desc:'سجل 5 ساعات تركيز',earned:focus>=300},{id:'reflect',icon:'▤',name:'متأمل',desc:'اكتب 7 سجلات يومية',earned:journals>=7},{id:'balance',icon:'⚖',name:'توازن',desc:'أنجز في النظريات الأربع',earned:unique>=4},{id:'fifty',icon:'🏅',name:'خمسون إنجازًا',desc:'سجل 50 مهمة مكتملة',earned:tasks>=50},{id:'goal',icon:'🎯',name:'محقق أهداف',desc:'أكمل هدفًا طويل المدى',earned:state.goals.some(g=>g.completed)}];}
function currentWeekKey(){const d=fromDateKey(dateKey());d.setDate(d.getDate()-((d.getDay()+6)%7));return dateKey(d);}
function getWeeklyChallenges(){const start=currentWeekKey(),days=Array.from({length:7},(_,i)=>addDays(start,i)),taskCount=days.reduce((n,k)=>n+dateLogs(k,'task').length,0),focusMin=days.reduce((n,k)=>n+dateLogs(k,'focus').reduce((a,x)=>a+(x.minutes||0),0),0),journalCount=days.filter(k=>state.journal[k]).length,theories=new Set(days.flatMap(k=>dateLogs(k,'task').map(x=>x.theoryKey))).size;return [{id:'tasks',title:'15 خطوة خلال الأسبوع',desc:'إنجاز مهام صغيرة موزعة على الأيام',progress:Math.min(taskCount,15),target:15,unit:'مهمة'},{id:'focus',title:'ساعتان من التركيز',desc:'جلسات تركيز عميق بلا استعجال',progress:Math.min(focusMin,120),target:120,unit:'دقيقة'},{id:'journal',title:'4 أيام من المراجعة',desc:'سجل ما تعلمته وما تريد تحسينه',progress:Math.min(journalCount,4),target:4,unit:'أيام'},{id:'balance',title:'التقدم في 3 نظريات',desc:'وزع جهدك على أكثر من جانب مهم',progress:Math.min(theories,3),target:3,unit:'نظريات'}];}
function renderRewards(){const challenges=getWeeklyChallenges(),week=currentWeekKey();state.challengeAwards=state.challengeAwards||{};state.challengeAwards[week]=state.challengeAwards[week]||{};let challengeAwarded=false;challenges.forEach(c=>{if(c.progress>=c.target&&!state.challengeAwards[week][c.id]){state.challengeAwards[week][c.id]=true;addRewardXP(20,10);challengeAwarded=true;}});if(challengeAwarded)save();const lv=levelInfo(),b=badges();$('weeklyChallenges').innerHTML=challenges.map(c=>`<div class="review-box"><b>${escapeHTML(c.title)}</b><p>${escapeHTML(c.desc)}</p><div class="progress-track" style="background:#e5ece7;margin:8px 0"><span style="width:${Math.round(c.progress/c.target*100)}%;background:var(--brand)"></span></div><small>${c.progress}/${c.target} ${c.unit} · ${state.challengeAwards[week][c.id]?'مكافأة حصلت عليها':'20 XP + 10 عملات عند الإكمال'}</small></div>`).join('');$('rewardHero').innerHTML=`<div><div class="eyebrow" style="color:#c7dfd5">رحلتك في BalanceOS</div><h3>${escapeHTML(lv.title)} · المستوى ${lv.level}</h3><p>كل خطوة صغيرة موثقة تضيف إلى خبرتك وتقدمك.</p></div><div class="reward-balance"><strong>${state.coins}</strong><span>عملة إنجاز</span></div>`;$('coinBalance').textContent=state.coins+' عملة';$('badgeGrid').innerHTML=b.map(x=>`<div class="achievement ${x.earned?'':'locked'}"><div class="badge-icon">${x.icon}</div><b>${x.name}</b><small>${x.desc}</small></div>`).join('');$('rewardShop').innerHTML=state.rewards.map(r=>`<div class="reward-item"><b>${escapeHTML(r.name)}</b><p>${escapeHTML(r.note||'مكافأة شخصية')}</p><div class="reward-cost">${r.cost} عملة</div><button class="btn btn-secondary" data-reward="${r.id}" ${state.coins<r.cost?'disabled':''}>استبدال</button></div>`).join('')||'<div class="empty-note">أضف مكافآت تحفزك على الاستمرار.</div>';}
function saveRewardFromDialog(e){e.preventDefault();const name=$('rewardNameInput').value.trim();if(!name)return;state.rewards.push({id:uid(),name,cost:int($('rewardCostInput').value,1,100000),note:$('rewardNoteInput').value});save();$('rewardDialog').close();renderRewards();toast('أضيفت المكافأة.');}
function rewardAction(e){const b=e.target.closest('[data-reward]');if(!b)return;const r=state.rewards.find(x=>x.id===b.dataset.reward);if(!r)return;if(state.coins<r.cost){toast('رصيد العملات غير كافٍ.','error');return;}if(!confirm(`استبدال ${r.cost} عملة مقابل «${r.name}»؟`))return;state.coins-=r.cost;state.redemptions.push({id:uid(),rewardId:r.id,name:r.name,cost:r.cost,date:dateKey(),redeemedAt:new Date().toISOString()});save();renderRewards();renderDashboard();toast('تم تسجيل استبدال المكافأة.');}
function loadSettings(){$('settingName').value=state.profile.name||'';$('settingDailyGoal').value=String(state.profile.dailyGoal||4);$('vacationMode').checked=!!state.profile.vacationMode;document.querySelectorAll('#restDaysEditor input').forEach(i=>i.checked=(state.profile.restDays||[]).includes(i.value));}
function saveSettings(){state.profile.name=$('settingName').value.trim()||'صاحب الخطة';state.profile.dailyGoal=int($('settingDailyGoal').value,1,8);state.profile.restDays=[...document.querySelectorAll('#restDaysEditor input:checked')].map(i=>i.value);const wasVacation=!!state.profile.vacationMode,nextVacation=$('vacationMode').checked;if(!wasVacation&&nextVacation){state.profile.vacationStreakSnapshot=calcStreak().current;state.profile.vacationStartedAt=dateKey();state.profile.vacationMode=true;}else if(wasVacation&&!nextVacation){const start=state.profile.vacationStartedAt,end=addDays(dateKey(),-1);if(start&&start<=end)state.profile.vacationRanges.push({start,end});state.profile.vacationMode=false;state.profile.vacationStartedAt=null;state.profile.vacationStreakSnapshot=null;}else state.profile.vacationMode=nextVacation;save();renderAll();toast('تم حفظ الإعدادات.');}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),4000);}
function exportBackup(){const payload={app:'BalanceOS',version:1,exportedAt:new Date().toISOString(),state};downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`BalanceOS_Backup_${dateKey()}.json`);toast('تم تجهيز النسخة الاحتياطية.');}
async function importBackup(e){const f=e.target.files?.[0];if(!f)return;try{const x=JSON.parse(await f.text());const incoming=x.state||x;if(incoming.schemaVersion!==1||!Array.isArray(incoming.theories)||!Array.isArray(incoming.logs))throw new Error('ملف النسخة لا يطابق إصدار BalanceOS.');incoming.challengeAwards=incoming.challengeAwards||{};incoming.theories=normalizeTemplate({theories:incoming.theories}).theories;if(!confirm('استعادة النسخة ستستبدل بيانات BalanceOS الحالية على هذا الجهاز. هل أنشأت نسخة من بياناتك الحالية؟'))return;state=incoming;save();populateSelectors();renderAll();loadSettings();toast('تمت استعادة النسخة.');}catch(err){toast(err.message||'تعذر استعادة الملف.','error');}finally{e.target.value='';}}
function exportCSV(){const rows=[['date','type','task','theory','minutes','xp','coins','note'],...state.logs.map(x=>[x.date,x.type,x.taskName||'',x.theoryName||x.theoryKey||'',x.minutes||'',x.xp||'',x.coins||'',x.note||''])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`BalanceOS_Activity_${dateKey()}.csv`);}
function exportTimePlannerConfig(){const config={tool:'TimePlanner Balance Builder',version:1,startDate:dateKey(),replaceGenerated:true,theories:state.theories.map(t=>({...t,color:Number(t.androidColor)||-227691,sections:t.sections.map(s=>({...s}))}))};downloadBlob(new Blob([JSON.stringify(config,null,2)],{type:'application/json'}),'BalanceOS_TimePlanner_Config.json');toast('تم تصدير إعدادات Time Planner.');}
function b64(buf){let bytes=new Uint8Array(buf),bin='';for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(bin);}
async function checkBackend(){try{const r=await fetch('./api/health',{cache:'no-store'});if(r.ok){const j=await r.json();$('timePlannerStatus').textContent=j.ok?'خادم التوافق المحلي متاح — يمكن إنشاء نسخة DB من إعداداتك.':'خادم التوافق غير جاهز.';const sample=await fetch('./api/sample');if(sample.ok&& !timePlannerBackupBase64)timePlannerBackupBase64=b64(await sample.arrayBuffer());}else{$('timePlannerStatus').textContent='خادم SQLite غير مرفق بهذا الاستضافة. يمكنك تصدير إعدادات JSON واستخدام Balance Builder المحلي.';}}catch(e){$('timePlannerStatus').textContent='لإنشاء DB مباشرة، شغّل BalanceOS عبر المشغل المحلي. على الاستضافة الثابتة استخدم تصدير إعدادات JSON ثم افتح Time Planner Balance Builder.';}}
function updateConnection(){$('connectionLabel').textContent=navigator.onLine?'حفظ محلي · '+(navigator.serviceWorker?.controller?'جاهز دون اتصال':'متصل'):'وضع عدم الاتصال';window.addEventListener('online',()=>{$('connectionLabel').textContent='متصل · البيانات محفوظة محليًا';});window.addEventListener('offline',()=>{$('connectionLabel').textContent='وضع عدم الاتصال · حفظ محلي';});}
async function importTimePlannerDb(e){const f=e.target.files?.[0];if(!f)return;try{timePlannerBackupBase64=b64(await f.arrayBuffer());$('timePlannerStatus').textContent=`تم تحميل ${f.name} في الذاكرة لجلسة التصدير الحالية.`;toast('تم تحميل نسخة Time Planner.');}catch(err){toast('تعذر قراءة ملف DB.','error');}finally{e.target.value='';}}
async function exportTimePlannerDB(){try{if(!timePlannerBackupBase64){const r=await fetch('./api/sample');if(!r.ok)throw new Error('لم يتم العثور على نسخة DB أصلية. اختر ملف Time Planner DB من الإعدادات أولًا.');timePlannerBackupBase64=b64(await r.arrayBuffer());}const health=await fetch('./api/health');if(!health.ok)throw new Error('أداة بناء SQLite غير متاحة. شغّل BalanceOS عبر Start_BalanceOS_Local.bat.');const payload={backupBase64:timePlannerBackupBase64,config:{tool:'TimePlanner Balance Builder',version:1,startDate:dateKey(),replaceGenerated:true,theories:state.theories.map(t=>({...t,color:Number(t.androidColor)||-227691,sections:t.sections.map(s=>({...s}))}))}};const r=await fetch('./api/timeplanner-build',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok)throw new Error(j.error||'تعذر بناء قاعدة البيانات.');const bin=atob(j.backupBase64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);downloadBlob(new Blob([bytes],{type:'application/octet-stream'}),`BalanceOS_TimePlanner_${dateKey()}.db`);$('timePlannerStatus').textContent=`تم إنشاء DB وفحص SQLite: ${j.meta.integrity} · ${j.meta.counts.tasks} مهمة · ${j.meta.counts.scheduledActivities} نشاط مجدول.`;toast('تم تنزيل نسخة Time Planner DB.');}catch(err){$('timePlannerStatus').textContent=err.message;toast(err.message,'error');}}
function resetApp(){if(!confirm('سيتم حذف جميع بيانات BalanceOS المحفوظة على هذا الجهاز وإعادة القوالب الأصلية. صدّر نسخة احتياطية أولًا. هل تتابع؟'))return;localStorage.removeItem(STORE_KEY);state=newState(templateOriginal);save();activeTheory='personal';renderAll();loadSettings();toast('تمت إعادة ضبط التطبيق.');}
function toast(message,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=message;$('toastRegion').appendChild(el);setTimeout(()=>el.remove(),3200);}
$('saveRewardBtn').addEventListener('click',()=>{});
window.addEventListener('beforeunload',save);
boot();
